import subprocess
import threading
from auto_config.generator.utils.logger import logger

TIMEOUT = 180


def execute_shell_command(cmd):
    logger.debug(f"[EXEC] Command={cmd}")
    ret = 0

    try:
        p = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, executable="/bin/bash")

        def worker():
            out, err = p.communicate()
            rc = p.returncode
            logger.debug(f"[EXEC] Command output=[{out.decode()}], error=[{err.decode()}], rc={rc}")

        thread = threading.Thread(target=worker)
        thread.start()
        thread.join(TIMEOUT)

        if thread.is_alive():
            logger.info(f"[EXEC] Command={cmd}, Timeout({TIMEOUT})")
            p.kill()
        else:
            ret = p.returncode
            if ret:
                logger.info(f"[EXEC] Command={cmd}, failed with return code: {ret}")
    except Exception as exc:
        logger.info(f"[EXEC] Command={cmd}, failed with exception: {exc}")
    return ret


def execute_sudo_command(cmd):
    cmd = f"sudo {cmd}"
    return execute_shell_command(cmd)
